"""EMS factory"""
from __future__ import absolute_import, division, print_function
from builtins import object
from taf.ul.trs_e2e_fw.lib.ems.ems_sim.emssim_interface import EmsSimInterface
from taf.ul.trs_e2e_fw.lib.utils.config_utils import get_config_variable
from taf.ul.trs_e2e_fw.lib.ems.netact.netact_interface import NetactInterface
from taf.ul.trs_e2e_fw.lib.ems.nom.nom_interface import NomInterface
from future import standard_library

standard_library.install_aliases()


class EmsFactory(object):
    """EMS factory"""
    def __init__(self):
        pass
        # self.config = ConfigHandler.get_config()

    def get_instance(self, config_device):
        """EMS interface"""
        ems_tool = get_config_variable(['ems', config_device, 'tool'])
        if ems_tool.lower() == 'emssim':
            return EmsSimInterface()
        elif ems_tool.lower() == 'netact':
            return NetactInterface()
        elif ems_tool.lower() == 'nom':
            return NomInterface()
